{
  "constraints": [
    {
      "constraint": "画面中必须出现至少一个圆筒状或管状的鱼雷发射通道结构。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "该管状结构必须具有可识别为鱼雷进出的端口（开口端、端盖或舱门）。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "管状结构必须表现为舰艇、潜艇或鱼雷艇等作战平台的武器系统组件，而非普通工业管道。",
      "polarity": "must_have",
      "variants": [
        "安装/归属环境 ∈ {甲板, 舷侧, 艇艏, 艇尾, 水下舱室, 独立武器装置展示}"
      ],
      "source": "desc"
    },
    {
      "constraint": "不得把鱼雷本体作为画面唯一主体而完全没有发射管结构。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "不得把发射管画成炮管、导弹垂直发射箱或普通输油/排水管道而缺少鱼雷发射通道特征。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面中出现鱼雷，则鱼雷必须与发射管口径匹配，表现为可装入发射管或从管口伸出。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
